<?php foreach ( canarw_public_footer_groups() as $canarw_group ) : ?><div><h3><?php echo esc_html( $canarw_group['title'] ); ?></h3><ul><?php foreach ( (array) $canarw_group['links'] as $canarw_link ) : ?><li><a href="<?php echo esc_url( canarw_resolve_url( $canarw_link['url'] ) ); ?>"><?php echo preg_match( '/\p{Arabic}/u', $canarw_link['label'] ) ? esc_html( $canarw_link['label'] ) : '<bdi dir="ltr">' . esc_html( $canarw_link['label'] ) . '</bdi>'; ?></a></li><?php endforeach; ?></ul></div><?php endforeach; ?>
